  FT["PH-H4566"] = {"id":"PH-H4566","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5970_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Tagapul-An in the Province of Samar","orig":"An Act Creating the Municipality of Tagapul-An in the Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5970","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5970_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4566-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Islands of Tagapul-an and Sibugay comprising the barrios of Sogod, Labang-Babay, Baquiw, Mataloto, Guinbarocan, Polang Bato, Balocawe, Nipa, and Luna in the Municipality of Almagre, Province of Samar, are separated from said municipality, and constituted into a distinct and independent municipality, to be known as the Municipality of Tagapul-an, same province. The seat of government of the new municipality shall be in the present site of Barrio Sogod."}},{"id":"PH-H4566-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be elected in the next general elections for local officials."}},{"id":"PH-H4566-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect on January first, nineteen hundred seventy if a majority of the voters ox the Municipality of Almagre vote in favor of the creation of the new municipality in a plebiscite to be held during the general elections of November, nineteen hundred sixty-nine.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p65"};
  FT["PH-H4567"] = {"id":"PH-H4567","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5971_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Constituting the Municipal Districts of Kasibu and Quezon in the Province of Nueva Vizcaya Into a Separate Highway Engineering District","orig":"An Act Constituting the Municipal Districts of Kasibu and Quezon in the Province of Nueva Vizcaya Into a Separate Highway Engineering District"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5971","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5971_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4567-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any law to the contrary notwithstanding, the municipal districts of Kasibu and Quezon, Province of Nueva Vizcaya, are hereby constituted into a separate highway engineering district, with principal offices in the municipal district of Kasibu, same province.\nThe highway district engineer for said engineering district shall be appointed in accordance with existing laws."}},{"id":"PH-H4567-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Communications is hereby authorized to set aside the necessary sums out of any unallotted funds or savings under the Department to carry into effect the provisions of this Act, and to transfer the necessary personnel, records, property, equipment and other supplies and materials to carry out the provisions of this Act. Thereafter, the sums necessary for the maintenance and support of the highway engineering district herein created shall be included annually in the General Appropriations Act."}},{"id":"PH-H4567-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p65"};
  FT["PH-H4568"] = {"id":"PH-H4568","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5972_1969.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Republic Act Numbered Forty-Six Hundred Forty-Five, Known as the Charter of the City of Olongapo","orig":"An Act Amending Republic Act Numbered Forty-Six Hundred Forty-Five, Known as the Charter of the City of Olongapo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5972","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5972_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 22 条，缺 14、15、16、17、18、19、20、21）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。 源文存在同号重出的条款（第 7 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4568-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven of Republic Act Numbered Forty-six hundred forty-five is hereby amended to read as follows:\n\""}},{"id":"PH-H4568-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Income, receipts and profits derived from sale and/or administration of alienable and disposable lands of the public domain.—All incomes, receipts and profits derived from the sale, disposition and/or administration of alienable and disposable lands of the public domain within the City of Olongapo shall accrue to a special fund of the city, notwithstanding any provision of law to the contrary, to be used exclusively to finance, directly or indirectly, the public works projects of the City of Olongapo, and shall not be used as a source of funds for the general budget of the City. Direct appropriation of funds from said Special Fund shall be established and made in accordance with a long-term development plan listing projects qualified herein and duly approved by the City Council, upon recommendation by the City Mayor: Provided, That unless such a long term development plan for the City of Olongapo is officially approved by the City Council, no appropriation from the said Special Fund may be legally made: Provided, further, That interests and dividends earned by the indirect use of said Special Fund to finance development projects may be used for the general budget of the City.\""}},{"id":"PH-H4568-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The same Act is further amended by inserting Section seven-A between sections seven and eight thereof to read as follows:\n\"Section 7-A. Lands exempted from public auction. —All commercial and residential lands within the City shall be exempted from the requirement of sale by public auction and the actual and/or legal possessor thereof, shall be given priority in acquiring the lands they occupy notwithstanding the provision of any law to the contrary.\""}},{"id":"PH-H4568-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Subsection (e), section ten of the same Act is hereby amended to read as follows:\n\"(e) To see that the executive officers and employees of the City properly discharge their respective duties and file administrative charges in accordance with the Civil Service Law against erring employees or officials who are receiving fully their salaries from the City and appointed by him or whose appointment is vested in him by the Decentralization Act and other laws, except the chief of police, notwithstanding the provision of any law to the contrary.\""}},{"id":"PH-H4568-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section twenty-two of the same Act is amended to read as follows:\n\""}},{"id":"PH-H4568-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Officers not to engage in certain transactions. —It shall be unlawful for any city officer, directly or indirectly, individually or as a member of a firm, to engage in any business transaction, with the city or with any of its authorized officials, boards, agents or attorneys whereby money is to be paid, directly or indirectly, out of the resources of the city to such person or firm.\""}},{"id":"PH-H4568-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section twenty-five of the same Act is hereby amended to read as follows:\n\"Section 25. The city fiscal—His powers, duties and compensation. —There shall be a city fiscal, who shall be the chief prosecuting officer of the city. There shall be eight assistant city fiscals, who shall be known as the first, second, third, fourth and fifth assistant city fiscals, respectively, and three assistant city fiscals with equal rank. The city fiscal and his assistants shall each receive the salary provided for in existing laws to be payable from national funds: Provided, however, That their salaries shall be paid from city funds until such time as the appropriation of the same has been included in the annual Appropriations Act. The city fiscal shall, subject to the general supervision of the Secretary of Justice, have the following general powers and duties:\n\"(a) He shall investigate all charges of crimes, misdemeanors, and violations of laws and city ordinances and prepare the necessary information or make the necessary complaints against the persons accused. He may conduct such investigation by taking oral evidence of reputed witnesses and for this purpose may, by subpoena or subpoena duces tecum summon witnesses to appear and testify under oath before him, or produce documents and other evidence before him, and the attendance of, or the production of documents and other evidence by an absent or recalcitrant witness may be enforced by application for \"warrant of arrest to the city court or the Court of First Instance.\n\"(b) He shall have charge of the prosecution of all crimes, misdemeanors and violations of laws and city ordinances triable in the Court of First Instance of Zambales and the city court, and shall discharge all the duties in respect to criminal prosecution enjoined by law upon provincial fiscals.\n\"(c) He shall cause to be investigated the causes of sudden deaths which have not been satisfactorily explained and when there is suspicion that the cause arose from unlawful acts or omissions of other persons or from foul play. For that purposes he may cause autopsies to be made in case it is deemed necessary and shall be entitled to demand and receive for the purpose of such investigation or autopsies the aid of the city health officer.\n\"(d) He shall at all times render such professional services as the Mayor or City Council may require, and shall have such powers and perform such duties as maybe prescribed by law or ordinances.\""}},{"id":"PH-H4568-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Paragraph (k) is hereby inserted between paragraph (j) and Section twenty nine of the same Act.\n\"(k) He and his representatives shall have the power to arrest violators of health laws, ordinances, rules and regulations and to recommend the revocation or suspension of the permits of the different establishments to the City Mayor for violation of health laws, ordinances, rules and regulations.\""}},{"id":"PH-H4568-A7_2","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section thirty of the same Act is hereby amended to read as follows:\n\"Section 30. The Deputy Chief of Police. —There shall be a deputy chief of police whose duties shall be to act as chief in the absence or incapacity of the chief of police and, under the direction of the chief of police to look after the discipline of the police force and perform such other duties as may be imposed upon him by the chief or prescribed by law or ordinance. He shall receive a compensation of not less than ten thousand two hundred pesos per annum.\""}},{"id":"PH-H4568-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section thirty-five of the same Act is hereby amended to read as follows:\n\"Section 35. Deputy Chief of the Fire Department. —There shall be a deputy chief of the fire department whose duties shall be to act as chief in the absence or incapacity of the chief of the fire department, and, under the direction of the chief of the fire department, to look after the discipline of the fire force and perform such duties as may be imposed upon him by the chief or prescribe by law or ordinance. He shall receive a compensation of not less than four thousand two hundred pesos per annum.\""}},{"id":"PH-H4568-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section eighty-two of the same Act is hereby amended to read as follows:\n\"Section 82. Regular and Acting Judges of City Court. —There shall be a city court for the City of Olongapo consisting of five branches, for which a presiding and four other judges shall be appointed, to be known, respectively, as judge of the first, second, third, fourth, and fifth branches. The city judges shall each receive a salary in accordance with existing laws: Provided, That such salaries shall be paid by the National Government.\n\"One judge shall be designated by the Secretary of Justice to try traffic cases exclusively. When the public interest so requires, the Secretary of Justice may designate any of the judges to hold sessions at night.\n\"The city court shall have the same jurisdiction in civil and criminal cases and the same incidental powers as are at present conferred by law upon municipal courts and such additional jurisdiction and powers as may hereafter be conferred upon them by law.\n\"In cases of absence, sickness or incapacity of any of the judges of any of the city court and in case of any vacancies in such offices, the Secretary of Justice may designate any municipal judge of any municipality in the Province of Zambales to act as judge of the city court of the City of Olongapo, with all the powers of a regular judge of said court, but such acting judge shall not receive any additional compensation during the time he is acting as such.\""}},{"id":"PH-H4568-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section eighty-three of the same Act is hereby amended to read as follows:\n\"Section 83. Clerks and employees of the City Court. —There shall be a Clerk of Court who shall be assisted by such number of deputies and other personnel as the exigencies of the service demand. The Clerk of Court, his deputies and other employees of the City Court shall be appointed by the City Mayor, in accordance with the Civil Service Law, rules and regulations.\n\"The Clerk of Court shall have charge of all properties, records and exhibits and such documents and papers of the Court. He shall keep the seal of the Court and affix it to all orders, judgments, certificates, records, and other documents issued by the Court. He shall keep a docket of the trials in the Court, wherein he shall record in a summary manner the names of the parties and the various proceedings in civil and criminal cases, the name of the defendant, the charge against him, the names of the witnesses, the date of the arrest, the appearance of the defendant, together with the fines and costs adjudged or collected in accordance with the judgment. He shall be notary public ex officio, and for purposes of this section, the Clerk of Court shall be head of office with the rank and salary of an assistant chief of a city department.\n\"The Clerk of the City Court shall, at the same time, be sheriff of the City and shall as such have the same powers and duties conferred by existing law to provincial sheriffs. The City Council may provide for such number of clerks in the Office of the Clerk of Court as the needs of the service may demand and their salaries shall conform to the rates prescribed under existing laws.\""}},{"id":"PH-H4568-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The same Act is further amended by inserting Section twenty-five-A between sections twenty-five and twenty-six thereof to read as follows:\n\"Section 25-A. The City Legal Officer. —There shall be a city legal officer who shall be appointed by the City Mayor from among members of the Bar in the City of Olongapo.\n\"The City Legal Officer shall have the rank, salary and privileges of a city department head and shall have the following powers and duties:\n\"(a) He shall personally or through any assistant represent the City in all civil cases wherein the City or any officer thereof, in his official capacity is a party, and shall prosecute and defend civil actions related to or connected with any city officer or interest: Provided, however, That the City Fiscal or any of his assistants shall assist him in such cases when requested by the City Mayor.\n\"(b) He shall, when directed by the Mayor, institute and prosecute in the City's interest, a suit on any bond, lease, or other contract and upon any breach or violation thereof.\n\"(c) He shall give his opinion in writing when requested by the Mayor or the City Council or any heads of the city departments through the City Mayor upon any question relating to the City.\n\"(d) He shall, when requested, attend meetings of the Council, draw up ordinances, contracts, bonds, leases, and other instruments involving any interest of the City, and inspect and pass upon such instruments already drawn.\n\"(e) He shall attend to other cases and he may be appointed as counsel de officio by any court.\n\"(f) He shall, whenever it is brought to his knowledge that any city officer or employee is guilty of neglect or misconduct in office, or that any person, firm or corporation holding or exercising any franchise or public privilege from the City has failed to comply with any condition, or to pay any consideration mentioned in the grant of such franchise or privilege, investigate or cause to be investigated the same and report to the Mayor.\n\"(g) He shall have the power to administer oaths and to act as notary public ex officio.\n\"(h) He shall have such other powers and perform such other duties as may be assigned to him by the City Mayor or as provided by law or ordinance.\""}},{"id":"PH-H4568-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The same Act is further amended by inserting Section one hundred fourteen-A between sections one hundred fourteen and one hundred fifteen thereof to read as follows:\n\"Section 114-A. Repealing Clause .—All laws, executive orders and proclamations or parts thereof inconsistent with any of the provisions of this Act are hereby repealed or modified accordingly.\""}},{"id":"PH-H4568-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p65"};
  FT["PH-H4569"] = {"id":"PH-H4569","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5973_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Section One of Republic Act Numbered Forty-Seven Hundred Fifty-Six","orig":"An Act Amending Section One of Republic Act Numbered Forty-Seven Hundred Fifty-Six"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5973","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5973_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4569-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Forty-seven hundred fifty-six is hereby amended to read as follows:\n\""}},{"id":"PH-H4569-A1_2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Bantacan, Katipunan, Cabinuangan, including Upper Aquibawa and Upper Agusan of Barrio ban Miguel, Magsaysay, Panay, Batinao, Fatima, Magangit, Camanlangan and San Roque in the Municipality of Compostela, Province of Davao, are hereby separated from said municipality and constituted into a distinct and independent municipality, to be known as the Municipality of New Bataan, same province. The seat of government shall be in Barrio Cabinuangan.\n\"The technical description of the said municipality follows, to wit: \"From Point \"10\" corner of Lot 10116 plans 2&mdashMunicipality of Nabunturan, thence to point \"7\" corner 3 of Lot 202 pls. to Municipality of Compostela to point \"1\" MBM No. 12 Municipality of Baganga, thence to point \"3\" MBM No. 13 Municipality of Caraga, thence to point \"4\" MBM No. 14 Municipality of Pantukan; thence to point \"5\" MBM No. 1 Municipality of Pantukan, thence to point of beginning at point \"10.\" \""}},{"id":"PH-H4569-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p65"};
  FT["PH-H4570"] = {"id":"PH-H4570","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5974_1969.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Iriga Telephone Company, Incorporated, a Franchise to Install, Operate and Maintain a Telephone System in the City of Iriga","orig":"An Act Granting Iriga Telephone Company, Incorporated, a Franchise to Install, Operate and Maintain a Telephone System in the City of Iriga"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 5974","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5974_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4570-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act and the provisions of Commonwealth Act Numbered One hundred and forty-six, as amended, and of the Constitution applicable thereto, there is hereby granted to the Iriga Telephone Company, Incorporated, hereinafter called the grantee, its successors or assigns, for a period of twenty-five years from the approval of this Act, the right and privilege to construct, operate and maintain in the City of Iriga, a telephone system to carry on the business of the electrical transmission of conversations and signals in said city. For this purpose, the grantee is hereby authorized to use all streets and public thoroughfares of the city for the construction, maintenance and, operation of all apparatus, conductors, and appliances necessary for the electrical transmission of conversations and signals to erect poles, string wires, build conduits, lay cables, and to construct, maintain and use such other approved and generally accepted means of electrical conduction in, on, over or under the public roads, highways, lands, bridges, streets, lanes and sidewalks of said city, and overhead or underground lines or on the surface of the ground as may be necessary and best adapted to said transmission."}},{"id":"PH-H4570-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All poles erected and all conduits constructed or used by the grantee shall be located in places designated by the city authorities; Provided, That all poles erected and used by the grantee or its successors shall be of such appearance as not to disfigure the streets, and the wires and cables carried by said poles and the underground cables shall be strong and laid in accordance with professional standards approved by the Public Service Commission; and said poles shall be of such a height as to maintain the wires and cables stretched on the same at a height at least fifteen feet above the level of the ground and said wires and cables shall be so placed as not to imperil the public safety, in accordance with a plan approved by the Public Service Commission: Provided, further, That whenever twenty-five or more pairs of wires or other conductors are carried on one line of poles in any place of the poblacion of said city, said wires or conductors shall be placed in one cable, and that whenever more than eight hundred pairs of wires or other conductors are carried on one line of poles, said wires or conductors shall be placed underground by the grantee, its successors or assigns, whenever ordered to do so by the Public Service Commission."}},{"id":"PH-H4570-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"For the purpose of erecting and placing the public or other supports of such wires or other conductors or of laying and maintaining underground said wires, cables or other conductors it shall be lawful for the grantee, its successors or assigns, to make excavations or lay conduits in any of the public places, highways, streets, alleys, lanes, avenues, sidewalks or bridges in the City of Iriga: Provided, however, That any public place, highway, street, alley, lane, avenue, sidewalk, or bridge disturbed, altered or changed by reason of the erection of poles or other supports, or the laying underground of wires or other conductors, or of conduits shall be repaired and restored to the satisfaction of the mayor of the city, and removing from the same all rubbish, dirt, refuse, or other material which may have been placed there or taken up in the erection of said poles or the laying of said underground conduits, leaving them in as good condition as they were before the work was done."}},{"id":"PH-H4570-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Whenever any person has obtained permission to use any of the streets of said city for the purpose of removing any building or in the prosecution of any city work or for any other cause whatever, making it necessary to raise or remove any of said wires or conduits which may obstruct or hinder the prosecution of said work, the said grantee, upon notice by the city council of the city, served upon said grantee, at least forty-eight hours in advance, shall raise or remove any of said wires or conduits which may hinder the prosecution of such work or obstruct the removal of said building, so as to allow the free and unobstructed prosecution of said work, and the person or entity at whose request the wires or poles or both structures have been removed shall pay one-half of the actual cost of replacing the poles or raising the wires and other conductors or structures. The notice shall be in the form of a resolution duly adopted by the city council and served upon the grantee or his duly authorized representative or agent by a person competent to testify as witness in a civil action, and in case of refusal or failure of the grantee to comply with such notice, the mayor of the city, with the proper approval of the city council first had, shall order such wires or conduits to be raised or removed at the expense of the grantee for the purpose aforesaid."}},{"id":"PH-H4570-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All apparatus and appurtenances used by the grantee, its successors or assigns, shall be modern and first class in every respect, and all telephone lines or installations used, maintained and operated in connection with this franchise by the grantee, its successors or assigns, shall be kept and maintained at all times in a satisfactory manner, so as to render an efficient and adequate telephone service, and it shall be the further duty of said grantee, its successors or assigns, whenever required to do so by the Public Service Commission to modify, improve, and change such telephone system for the electrical transmission of conversations and signals by means of electricity in such manner and to such extent as the progress of science and improvements in the method of electrical transmission of conversations and signals by means of electricity may make reasonable and proper."}},{"id":"PH-H4570-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall keep a separate account of the gross receipts of its telephone business and shall furnish the Auditor General and the Treasurer of the Philippines a copy of such account not later than the thirty-first day of July of each year for the twelve months preceding the first day of July."}},{"id":"PH-H4570-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its business, real estate, buildings, and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay."}},{"id":"PH-H4570-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Within sixty days, from the approval of this Act, the grantee shall file with the Public Service Commission its application for a certificate of public necessity and convenience. In case of failure to make said application within the period established, the franchise shall become null and void."}},{"id":"PH-H4570-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not commence any construction whatever pursuant to this franchise without first obtaining a certificate of public necessity and convenience from the Public Service Commission of the form and character provided for in Commonwealth Act Numbered One hundred and forty-six, as amended, specifically authorizing such construction. The grantee shall not exercise any right or privilege under this franchise without first having obtained such certificate of public necessity and convenience from the Public Service Commission. The Public Service Commission shall have the power to issue such certificate of public necessity and convenience whenever it shall, after due hearing, determine that such construction or such exercise of the rights and privileges under this franchise is necessary and proper for the public convenience, and the Commission shall have the power in so approving to impose such conditions as to construction, equipment, maintenance, service or operation as the public convenience and interests may reasonably require, and such certificate shall state the date on which grantee shall commence construction and the period within Which the work shall be completed. In order to avail himself of the rights granted by such certificate of public necessity and convenience, the grantee shall file with the Public Service Commission, within such period as said Commission shall fix, its written acceptance of the terms and conditions of this franchise and of the certificate, together with the document evidencing that the deposit required in Section ten has been made. In the event that the grantee shall not commence the telephone service referred to in the certificate obtained and filed as herein provided within such period as the Public Service Commission shall have fixed, said Commission may declare said certificate null and void and the deposit made pursuant to Section ten of this Act forfeited to the National Government unless the grantee shall have been prevented from doing so by fortuitous cause or force majeure, usurped or military power, martial law, riot, uprising, or other inevitable cause: Provided, however, That if the grantee shall have been prevented by one or more of all such causes from commencing the telephone service within the period specified, the time during which it shall have been so prevented shall be added to said period: Provided, further, That failure on the part of the grantee to accept the conditions of this franchise and those imposed in the certificate of public necessity and convenience shall automatically void this franchise."}},{"id":"PH-H4570-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Upon the written acceptance of the terms and conditions of this franchise, the grantee shall deposit with the National Treasurer one thousand pesos or negotiable bonds of the Government of the Philippines or other securities approved by the Secretary of Public Works and Communications, of the face value of one thousand pesos, as an earnest of good faith in accepting this franchise and a guaranty that, within six months from the date of the granting by the Public Service Commission of a certificate of public necessity and convenience authorizing the construction and operation by the grantee of a telephone service in the City of Iriga, the grantee, its successors or assigns, will be completely provided with the necessary equipment and ready to begin operation in accordance with the terms of this franchise: Provided, That if the deposit is made in money, the same shall be deposited at interest in some interest-paying bank approved by the Secretary of Public Works and Communications, and all interest accruing and due on such deposit shall be collected by the Treasurer of the Philippines and paid to the grantee, its successors or assigns, on demand: And provided, further, That if the deposit made with the Treasurer of the Philippines be in negotiable bonds of the Government of the Philippines or other interest-bearing securities approved by the Secretary of Public Works and Communications, the interest on such bonds or securities shall be collected by the Treasurer of the Philippines and paid over to the grantee, its successors or assigns, on demand.\nShould the said grantee, its successors or assigns, for any other cause than the act of God, the public enemy, usurped or military power, martial law, riot, civil commotion, or inevitable cause, fail, refuse, or neglect to begin within twelve months from date of the granting of said certificate of public necessity and convenience, the business of transmitting messages by telephone, or fail, refuse or neglect to be fully equipped and ready to operate within twelve months from the date of the granting of said certificate of public necessity and convenience, the telephone service in the City of Iriga applied for by the grantee according to the terms of this franchise, then the deposit prescribed by this section to be made with the Treasurer of the Philippines, whether in money, bonds, or other securities, shall become the property of the National Government as liquidated damages caused to such Government by such failure, refusal, or neglect, and thereafter no interest on said bonds or other securities deposited shall be paid to the grantee, its successors or assigns. Should the said grantee, its successors or assigns, begin operating the business of transmitting messages by telephone and be ready to operate according to the terms of the franchise, the telephone service in the City of Iriga, within twelve months from the date of the granting of said certificate of public necessity and convenience, then and in that event the deposit prescribed by this section shall be returned by the National Government to the grantee, its successors or assigns, upon recommendation of the Public Service Commission, as soon as the telephone service in said city applied for by the grantee has been installed in accordance with the terms of this franchise: Provided, further, That all the time during which the grantee, its successors or assigns, may be prevented from carrying out the terms and conditions of this franchise by any of said causes shall be added to the time allowed by this franchise for compliance with its provisions."}},{"id":"PH-H4570-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the city auditor or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts and the net receipts for the quarter past and the general condition of the business."}},{"id":"PH-H4570-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The rights herein granted shall not be exclusive, and the rights and power to grant to any corporation, association, or person other than the grantee a franchise for the telephone or electrical transmission of messages or signals shall not be impaired or affected by the granting of this franchise: Provided, That the poles erected, wires strung or cables or conduits laid by virtue of any franchise for telephone, or other electrical transmission of messages and signals granted subsequent to this franchise shall be so placed as not to impair the efficient and effective transmission of conversations or signals under this franchise by means of poles erected, wires strung, or cables or conduits actually laid and in existence at the time of the granting of said subsequent franchise: And provided, further, That the Public Service Commission, after hearing both parties interested, may compel the grantee of this franchise or its successors or assigns, to remove, relocate, or replace its poles, wires, or conduits; but in such case the reasonable cost of the removal, relocation, or replacement shall be paid by the grantee of the subsequent franchise, or his successors or assigns, to the grantee of this franchise or its successors or assigns."}},{"id":"PH-H4570-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments harmless from all claims, accounts, demands, or action arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the telephone or other electrical transmission system ,of the said grantee, its successors or assigns."}},{"id":"PH-H4570-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The rates for the telephone service, flat rates as well as the measured rates, shall be subject to the approval of the Public Service Commission.\nThe monthly rates for telephone having a metallic circuit within the limits of the poblacion of the city shall also be approved by the Public Service Commission."}},{"id":"PH-H4570-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The grantee shall not, without the previous and explicit approval of the Congress of the Philippines, directly or indirectly, transfer, sell or assign this franchise to any person, association, company, or corporation, or other mercantile or legal entity."}},{"id":"PH-H4570-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The grantee may install, operate, maintain, purchase or lease such telephone stations, lines, cables or system, as is, or are, convenient or essential to efficiently carry out the purpose of this franchise: Provided, however, That the grantee, its successors or assigns, shall not, without the permission of the Public Service Commission first had, install, operate, maintain, purchase or lease such stations, lines, cables, or system."}},{"id":"PH-H4570-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The Philippine Government shall have the privilege, without compensation, of using the poles of the grantee to attach ten-pin crossarm, and to install, operate and maintain wires of its telephone system thereon: Provided, however, That the Bureau of Telecommunications shall have the right to place additional crossarms and wires on the poles of the grantee by paying a compensation, the rate of which is to be agreed upon by the Director of Telecommunications and the grantee: Provided, further, That in case of disagreement as to the rate of contract rental, same shall be fixed by the Public Service Commission. The City of Iriga shall also have the privilege, without compensation, of using the poles of the grantee, to attach one standard crossarm, and to install, operate and maintain wires of a local police and fire alarm system; but the wires of such telegraph lines, police or fire alarm system, shall be placed and strung in such manner as to cause no interference with or damage to the wires of the telephone service of the grantee."}},{"id":"PH-H4570-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn to the Government said system and all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H4570-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The grantee is authorized to mortgage its franchise to individual or banking or financial institutions for purposes of expanding its business under this franchise."}},{"id":"PH-H4570-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"In consideration of this franchise, the grantee shall pay n tax equivalent to five per cent of its gross income."}},{"id":"PH-H4570-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p65"};
  FT["PH-H4571"] = {"id":"PH-H4571","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5975_1969.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Riverside Marketing Corporation a Permit to Construct, Establish, Operate and Maintain Private Fixed, Point-To-Point, Land-Based, and Land-Mobile or Portable Radio Stations for the Transmission and Reception of Wireless Intelligence on Radiotelegraph or Radiotelephone Within the Philippines","orig":"An Act Granting Riverside Marketing Corporation a Permit to Construct, Establish, Operate and Maintain Private Fixed, Point-To-Point, Land-Based, and Land-Mobile or Portable Radio Stations for the Transmission and Reception of Wireless Intelligence on Radiotelegraph or Radiotelephone Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5975","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5975_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4571-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Riverside Marketing Corporation, its successors or assigns, a permit to construct, establish, operate and maintain in such places in the Philippines where it operates or transacts its business or renders its services, subject to the approval of the Secretary of Public Works and Communications or any licensing authority, private fixed, point-to-point, land-based, and land-mobile or portable radio stations for the transmission and reception of wireless intelligence on radiotelegraph or radiotelephone, inclusive of but not limited to facsimile, radioteletype, nationally and internationally, each station to be provided with radio transmitting equipment and or receiving equipment as necessary."}},{"id":"PH-H4571-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The permit herein granted shall continue to be in force during the time that the grantee, its successors or assigns, conducts its business or services at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of at least two radio stations be begun within two years from the date of the approval of this Act,"}},{"id":"PH-H4571-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic public telecommunications business in the Philippines, it being understood that the purpose of this permit is to secure to the grantee, its successors or assigns, the right to construct, install, operate and maintain its radio stations herein granted at the places above-mentioned for the primary purpose of promoting and protecting the business and other interests of the grantee."}},{"id":"PH-H4571-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act, shall be engaged in communications regarding the grantee's business interest: Provided, however, That the grantee may allow affiliate, allied or associated companies to use any of its facilities on a non-profit basis."}},{"id":"PH-H4571-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its radio stations herein granted in the very low frequency, low frequency, medium frequency, high frequency, very high frequency, ultra high frequency, super high frequency and extreme high frequency that shall be assigned to it by the Secretary of Public Works and Communications, or by any licensing authority."}},{"id":"PH-H4571-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H4571-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors and assigns, shall hold the national, provincial and municipal governments of the Philippines free from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H4571-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H4571-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, or other national emergency and when public safety requires, to cause the closing of the grantee's radio station or stations or to authorize the temporary use or possession thereof by any department of the Government upon just compensation to the grantee for the use of said stations during the continuance of the national emergency."}},{"id":"PH-H4571-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H4571-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"In the event of any individual, partnership or corporation receiving from the Congress a similar permit in which there shall be any term or terms more favorable than those herein granted, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said individual, partnership or corporation."}},{"id":"PH-H4571-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p65"};
  FT["PH-H4572"] = {"id":"PH-H4572","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5978_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Balabagan in the Province of Lanao Del Sur","orig":"An Act Creating the Municipality of Balabagan in the Province of Lanao Del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5978","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-07-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5978_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4572-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios and sitios of Lalabuan, Barorao, Purakan, Baguiangan, Kalilangan, Itil, Banago, Butuan, Budas, Igahay, Magolalung, Daguan, Balabagan, Sipang and Bakikis in the municipalities of Malabang and Dianaton, Lanao del Sur, are hereby segregated from said municipalities and organized into an independent municipality to be known as the Municipality of Balabagan. The seat of government of the new municipality shall be in the present site of Barrio Banago."}},{"id":"PH-H4572-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect as of March sixteen, nineteen hundred and sixty.\nApproved, July 5, 1969."}}],"pack":"ph-p65"};
  FT["PH-H4573"] = {"id":"PH-H4573","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5980_1969.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Regulating the Organization and Operation of Financing Companies.","orig":"An Act Regulating the Organization and Operation of Financing Companies."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5980","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-08-04","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5980_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4573-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the \"Financing Company Act.\""}},{"id":"PH-H4573-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. It is hereby declared to be the policy of the State to regulate the activities of financing companies to place their operations on a sound, stable and efficient basis, so that they may be in a better position to extend effective service in a fair manner to the general public and to industry, commerce and agriculture; to curtail and prevent acts or practices prejudicial to the public interests."}},{"id":"PH-H4573-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. As used in this Act, the term:\n(a) \"Financing companies,\" hereinafter called companies, are corporations, or partnerships, except those regulated by the Central Bank of the Philippines, the Insurance Commissioner and the Cooperatives Administration Office, which are primarily organized for the purpose of extending credit facilities to consumers and to industrial, commercial, or agricultural enterprises, either by discounting or factoring commercial papers on accounts receivable, or by buying and selling contracts, leases, chattel mortgages, or other evidences of indebtedness, or by leasing of motor vehicles, heavy equipment and industrial machinery, business and office machine and equipment, appliances and other movable property;\n(b) \"Securities and Exchange Commission\" shall mean the office of the Securities and Exchange Commission of the Philippines;\n(c) \"Credit\" shall mean any loan, mortgage, deed of trust, advance, or discount; any conditional sales contract, any contract to sell, or sale or contract of sale of property or service, either for present or future delivery, under which, part or all the price is payable subsequent to the making of such sale or contract; any rental-purchase contract; any option, demand, lien, pledge, or other claim against, or for the delivery of, property or money, any purchase, or other acquisition of or any credit upon the security of, any obligation or claim arising out of the foregoing; and any transaction or series of transactions having a similar purpose or effect; and\n(d) \"Purchase discount\" is the difference between the value of the receivable purchased or credit assigned, and the net amount paid by the finance company for such purchase or assignment, exclusive of fees, service charges, interests and other charges incident to the extension of credit."}},{"id":"PH-H4573-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Grant of Authority to the Securities and Exchange Commission. The Securities and Exchange Commission of the Philippines is hereby empowered to enforce the provisions of this Act."}},{"id":"PH-H4573-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Limitation on Purchase Discount, Fees, Service and Other Charges. In the case of assignments of credit or the buying of installment papers, accounts, receivables and other evidences of indebtedness by financing companies, the purchase discount, exclusive of interest and other charges shall be limited to fourteen (14%) per cent of the value of the credit assigned or the value of the installment papers, accounts receivable and other evidence of indebtedness purchased based on a period of twelve (12) months or less, and to one and one-sixth (1 1/6%) per cent of each additional month or fraction thereof in excess of twelve months, regardless of the terms and conditions of the assignment or purchase.\nIn the case of assignment of credit or the buying of installment papers, accounts receivable and other evidence of indebtedness pertaining to appliances, furniture, and office equipment, the purchase discount, exclusive of interest charges, shall be limited to eighteen (18%) per cent of the value at maturity of the credit assigned or receivable purchased, based on a period of twelve months or less, and to one and one-half (1 1/2%) per cent for each additional month or fraction thereof in excess of twelve months, regardless of the terms and conditions of the assignment or purchase.\nIn case of factoring of accounts receivables or other evidences of indebtedness, the discounting rate that can be charged, exclusive of interest and other charges, shall not exceed two per cent of the value of the credit assigned or receivable purchased for every thirty days, regardless of the terms and conditions of the factoring agreement.\nThe Securities and Exchange Commission, in consultation with the financing companies, shall prescribe reasonable limitations on fees, service and other charges which shall be uniform for all financing companies, taking into consideration the nature of the transaction or service and the cost thereof to the financing companies."}},{"id":"PH-H4573-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Form of Organization. Financing companies shall be organized in the form of stock corporations or general partnerships at least sixty per centum of the capital of which is owned by citizens of the Philippines and shall have a paid-up capital of not less than five hundred thousand pesos: Provided, however , That financing companies duly existing and operating before the approval of this Act shall comply with the requirement that sixty (60%) per centum of the capital be owned by citizens of the Philippines within one year from the date of said approval."}},{"id":"PH-H4573-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Requirement for Registration. Aside from requiring compliance with the provisions of the Corporation Law and the New Civil Code in case of partnership the Securities and Exchange Commission shall not register the articles of incorporation or the articles of partnership of any financing company unless his office is satisfied on the evidence submitted to it that:\n(a) all the requirements of existing laws to engage in the business for which the applicant is proposed to be incorporated or organized have been complied with;\n(b) the organization, direction, and administration, as well as the integrity and responsibility of the organizers and administrators reasonably assume the protection of the interest of the general public; and\n(c) all the requirements of this Act have been complied with: Provided , That financing companies duly incorporated or registered prior to the approval of this Act, and which are actually existing and operating as such, shall file an information sheet with the Securities and Exchange Commission in the form to be prescribed by the Securities and Exchange Commission within sixty (60) days after notice from the said Commission. No person, association, partnership, or corporation shall hold itself out as doing business as a \"financing company\" or \"finance and investment company\" or any other title or name tending to give the public the impression that it is engaged in the operations and activities of a financing company, unless so authorized under this Act."}},{"id":"PH-H4573-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Citizenship Requirement of the Board of Directors. In the case of a corporation, at least two-thirds of all members of the Board of Directors of any financing company which may be established after the approval of this Act, shall be citizens of the Philippines. In the case of partnerships, all the managing partners must be citizens of the Philippines. In the case of corporations and partnerships existing before the approval of this Act compliance with this provisions shall be required within the period of one year from the date of said approval."}},{"id":"PH-H4573-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Revocation and Suspension of Registration. The Securities and Exchange Commission may revoke or suspend the registration of any financing company by entering an order to this effect together with its findings in respect thereto, if upon investigation into the affairs of said financing company or complaint by any person, it shall appear that:\n(a) it is insolvent; or\n(b) it has violated any provision of this Act."}},{"id":"PH-H4573-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Penalty. A fine of not less than five thousand pesos (P5,000.00) and not more than ten thousand pesos (P10,000.00) or imprisonment for not more than six months or both, at the discretion of the court, shall be imposed upon:\n1. Persons, associations, partnerships, or corporations, including the managing officer thereof, that shall:\n(a) Engage in the business of a financing company without authority from the Securities and Exchange Commission;\n(b) Hold themselves out to be a financing company, either through advertisement in whatever form, whether in its stationary, commercial paper, or other document, or through other representations without authority;\n(c) Make use of a trade or firm name containing the words \"financing company\" or \"finance company\" or \"finance and investment company\" or any other designation that would give the public the impression that it is engaged in the business of a financing company as defined in this Act without authority; and\n(d) Violate the provisions of this Act.\n2. Any officer, employee, or agent of a financing company who shall:\n(a) Knowingly and willingly make any statement in any application, report, or document required to be filed under this Act, which statement is false or misleading with respect to any material fact; or\n(b) Overvalue or aid in overvaluing any security for the purpose of influencing in any way the action of the company on any loan, or discounting line.\n3. Any officer, employee, or examiner of the Securities and Exchange Commission directly charged with the implementation of this Act who shall commit, connive, aid, or assist in the commission of acts enumerated under subsections 1 and 2 of this Section."}},{"id":"PH-H4573-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Separability of Clause. If any provision or section of this Act or the application thereof to any person or circumstances is held invalid, the other provisions or sections hereof and the application of such provisions or sections to other persons or circumstances shall not be affected thereby."}},{"id":"PH-H4573-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Repealing Clause. All Acts inconsistent with this Act are hereby repealed."}},{"id":"PH-H4573-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: August 4, 1969"}}],"pack":"ph-p65"};
